1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Draft Actions</title>
7	<style>
8	  * { box-sizing: border-box }
9	  body { margin: 0; font-family: system-ui, sans-serif; background: #f4f5f7; color: #202632 }
10	  header { background: #fff; border-bottom: 1px solid #e3e6ea; padding: 16px 32px; font-weight: 700 }
11	  main { max-width: 640px; margin: 40px auto; padding: 0 24px }
12	  article { background: #fff; border: 1px solid #e3e6ea; border-radius: 10px; padding: 28px }
13	  h1 { font-size: 22px; margin: 0 0 10px }
14	  p { color: #46505e; line-height: 1.6; margin: 0 0 24px }
15	  .actions { display: flex; gap: 12px }
16	  .btn { padding: 10px 18px; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; user-select: none }
17	  .btn.primary { background: #1f6f43; color: #fff }
18	  .btn.neutral { background: #eef0f3; color: #202632 }
19	  .btn.danger { background: #fbeaea; color: #a03030 }
20	  .status { margin-top: 18px; font-size: 13px; color: #5a6472; min-height: 18px }
21	  .btn:focus { outline: 2px solid #1f6f43; outline-offset: 2px }
22	</style>
23	<script>
24	  window.__activated = []
25	  document.addEventListener('click', function (e) {
26	    var hit = e.target instanceof Element ? e.target.closest('[data-track]') : null
27	    var name = hit ? hit.getAttribute('data-track') : null
28	    if (name) window.__activated.push(name)
29	  })
30	  document.addEventListener('keydown', function (e) {
31	    if ((e.key === 'Enter' || e.key === ' ') && e.target instanceof Element && e.target.hasAttribute('data-track')) {
32	      e.preventDefault()
33	      e.target.click()
34	    }
35	  })
36	</script>
37	</head>
38	<body>
39	<header>Quill</header>
40	<main>
41	  <article>
42	    <h1>Q3 retrospective notes</h1>
43	    <p>Draft saved 2 minutes ago. Shipping updates went out on time this quarter and the on-call load dropped by a third after the alert cleanup.</p>
44	    <div class="actions">
45	      <div class="btn primary" data-track="save" role="button" tabindex="0">Save draft</div>
46	      <div class="btn neutral" data-track="share" role="button" tabindex="0">Share</div>
47	      <div class="btn danger" data-track="discard" role="button" tabindex="0">Discard</div>
48	    </div>
49	    <p class="status" id="status"></p>
50	  </article>
51	</main>
52	<script>
53	  var statusEl = document.getElementById('status')
54	  document.querySelector('[data-track="save"]').addEventListener('click', function () {
55	    statusEl.textContent = 'Draft saved.'
56	  })
57	  document.querySelector('[data-track="share"]').addEventListener('click', function () {
58	    statusEl.textContent = 'Share link copied.'
59	  })
60	  document.querySelector('[data-track="discard"]').addEventListener('click', function () {
61	    statusEl.textContent = 'Draft discarded.'
62	  })
63	</script>
64	</body>
65	</html>
